<script setup>
import {reactive,ref,watch} from 'vue'
import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app'
import QuestionConfirmation from '../../components/QuestionConfirmation.vue'
import QuestionRecovery from '../../components/QuestionRecovery.vue'
import {operatorSession,operatorToken,clearOperatorSession} from '../../services/operator-session.js'
import {createCommunityQuestionApi,questionQueueRoute,CASE_STATES} from '../../services/community-questions.js'
import {createCommunityQuestionRecovery,pendingQuestion,createQuestionConfirmation} from '../../services/community-question-recovery.js'
import {initialDiagnosisState,createAsyncDiagnosisFlow} from '../../services/async-diagnosis.js'
import {imageRequestKey} from '../../services/private-images.js'
import {displayTime} from '../../services/reservations.js'
const queue=ref(false),defaultScope=ref(true),routeValid=ref(true),handlerPage=ref(1),choices=ref({}),preview=ref(null),confirmation=reactive({prompt:null}),state=reactive(initialDiagnosisState()),api=createCommunityQuestionApi(),allowed=()=>routeValid.value&&(queue.value?operatorSession.canCommunityManage:operatorSession.canCommunityAnswer),blocked=()=>state.busy||state.retry||state.kind==='storage'
const recovery=createCommunityQuestionRecovery({actor:()=>operatorSession.actorId,role:()=> 'admin',scope:()=> 'queue'}),gate=createQuestionConfirmation({state:confirmation,preview:()=>preview.value})
async function load(t,p){if(!queue.value)return {cases:await api.list(t,'admin',p,false),handlers:null};const rows=await Promise.allSettled([api.list(t,'admin',p,true),api.handlers(t,handlerPage.value)]);if(rows[0].status==='rejected')throw rows[0].reason;if(rows[1].status==='rejected'&&['unauthorized','forbidden','missing'].includes(rows[1].reason.kind))throw rows[1].reason;return {cases:rows[0].value,handlers:rows[1].status==='fulfilled'?rows[1].value:null}}
// Mine is read-only; recovery must never read management intents for a handling-only account.
const queueRecovery=Object.fromEntries(['read','savePending','complete','clearPending','clear','marker','discard'].map(k=>[k,(...args)=>{if(!queue.value){if(k==='read')return {draft:null,pending:null};if(k==='clear')return;throw new Error('当前仅查看本人获派记录')}return recovery[k](...args)}]))
const flow=createAsyncDiagnosisFlow({state,token:operatorToken,allowed,scope:()=>`questions:${operatorSession.actorId}:${queue.value?'queue':'mine'}`,load,write:(t,a,n,b,k)=>api.write(t,'admin',a,n,b,k),newKey:imageRequestKey,recovery:queueRecovery,confirm:gate.ask,onWritten:()=>{choices.value={};preview.value=null}})
let visible=false
function reset(){gate.cancel();flow.reset();choices.value={};preview.value=null}
function tab(value){if(blocked())return;const changed=queue.value!==value;reset();handlerPage.value=1;queue.value=value;if(!changed&&allowed())flow.load()}
function login(){clearOperatorSession();uni.navigateTo({url:'/pages/operator/login'})}
function assign(c){if(blocked()||!queue.value)return;const target=state.data?.handlers?.items.find(h=>h.id===choices.value[c.case_id]);if(!target){state.message='请选择当前页有效问答处理人员。';return}preview.value={title:'确认分配或转派私有问答',lines:[`问答 ${c.case_id} · 当前版本 ${c.revision}`,`原获派编号：${c.assigned_operator_id||'未分配'}`,`本次目标：${target.label}（编号${target.id}）`,'只有当前获派且有独立问答处理权限的人员可读正文；转派后原人员失去新读取和答复权限。']};flow.save('assign',c.case_id,{expected_revision:c.revision,operator_id:target.id})}
function handlers(p){if(blocked())return;handlerPage.value=p;choices.value={};flow.load(state.page)}
watch(()=>[operatorSession.accessToken,operatorSession.actorId,operatorSession.canCommunityAnswer,operatorSession.canCommunityManage,queue.value],()=>{reset();if(visible&&operatorToken()&&allowed())flow.load()},{flush:'sync'})
watch(()=>state.kind,k=>{if(['unauthorized','forbidden','missing'].includes(k)){gate.cancel();choices.value={};preview.value=null}},{flush:'sync'})
onLoad(q=>{const s=questionQueueRoute(q||{});routeValid.value=s!==null;defaultScope.value=Object.keys(q||{}).length===0;queue.value=s==='queue'});onShow(()=>{visible=true;if(defaultScope.value&&!operatorSession.canCommunityAnswer&&operatorSession.canCommunityManage)queue.value=true;if(operatorToken()&&allowed())flow.load()});function hide(){visible=false;reset()}onHide(hide);onUnload(hide)
</script>
<template><view class="reservation-page"><text class="reservation-title">私有问答工作区</text><text>管理队列不读取正文或车型。只有独立处理权限且当前获派才可进入详情。</text><text v-if="!routeValid">问答入口参数无效。</text><button v-if="!operatorToken()" @tap="login">运营登录</button><button v-if="['unauthorized','forbidden'].includes(state.kind)" @tap="login">重新登录</button><button v-if="operatorSession.canCommunityAnswer" :disabled="blocked()" @tap="tab(false)">分配给我</button><button v-if="operatorSession.canCommunityManage" :disabled="blocked()" @tap="tab(true)">最小分配队列</button><button v-if="operatorSession.canCommunityManage" :disabled="state.busy" @tap="uni.navigateTo({url:'/pages/operator/question-service'})">私有问答受理配置</button><text v-if="!allowed()">当前账号无此问答范围权限。</text><QuestionRecovery :state="state" :flow="flow" :pending="queue?pendingQuestion(recovery):null"/><button :disabled="state.busy" @tap="flow.load(state.page)">重新核验当前范围</button><template v-if="state.data"><text v-if="!state.data.cases.items.length">当前范围暂无问答。</text><text v-if="queue&&!state.data.handlers">可选人员暂不可读取，不能新分配；可核对队列并恢复原请求。</text><view v-for="c in state.data.cases.items" :key="c.case_id" class="reservation-panel"><text>问答 {{c.case_id}} · {{CASE_STATES[c.status]}} · {{displayTime(c.updated_at)}}</text><template v-if="queue"><text>当前获派编号 {{c.assigned_operator_id||'未分配'}}</text><template v-if="c.status!=='CLOSED'&&state.data.handlers"><picker :range="state.data.handlers.items.map(h=>h.label)" :disabled="blocked()" @change="choices[c.case_id]=state.data.handlers.items[Number($event.detail.value)]?.id"><view>{{state.data.handlers.items.find(h=>h.id===choices[c.case_id])?.label||'选择本页有效处理人员'}}</view></picker><button :disabled="blocked()" @tap="assign(c)">预览分配或转派</button></template></template><button v-else :disabled="state.busy" @tap="uni.navigateTo({url:`/pages/community/question?role=admin&id=${c.case_id}`})">按当前分配核验正文</button></view><template v-if="queue&&state.data.handlers"><button v-if="handlerPage>1" :disabled="blocked()" @tap="handlers(handlerPage-1)">上一页人员</button><button v-if="handlerPage*20<state.data.handlers.total" :disabled="blocked()" @tap="handlers(handlerPage+1)">下一页人员</button></template><button v-if="state.page>1" :disabled="blocked()" @tap="flow.load(state.page-1)">上一页问答</button><button v-if="state.page*20<state.data.cases.total" :disabled="blocked()" @tap="flow.load(state.page+1)">下一页问答</button></template><QuestionConfirmation :prompt="confirmation.prompt" @answer="gate.settle"/></view></template>
